"""Validate local status page password complexity (Meraki rules)."""
import sys
import re

pwd = sys.argv[1]

is_valid = True
if len(pwd) < 14:
    is_valid = False
elif not re.search(r'[0-9]', pwd):
    is_valid = False
elif not re.search(r'[A-Z]', pwd):
    is_valid = False
elif not re.search(r'[a-z]', pwd):
    is_valid = False
elif not re.search(r'[!@#$%^&*(),.?":{}|<>]', pwd):
    is_valid = False

result = is_valid

"""
Record LSP Network Result — append one per-network event (loop script).

  argv[1]  Local - Processed Networks
  argv[2]  Network ID
  argv[3]  Network name
  argv[4]  HTTP status code (final attempt)
  argv[5]  API error detail
  argv[6]  Update path: standard | retry_no_remote

Script query: updated_list
"""

import sys
import json

SUCCESS_CODES = frozenset({200, 204})
OK_OUTCOMES = frozenset({"updated", "updated_no_remote"})


def parse_list(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def clean_detail(raw):
    text = str(raw or "").strip()
    if not text:
        return ""
    if text.startswith("[") or text.startswith("{"):
        try:
            parsed = json.loads(text)
            if isinstance(parsed, list):
                return "; ".join(str(item) for item in parsed)
            return str(parsed)
        except Exception:
            return text
    return text


def build_message(outcome, status_code, detail):
    labels = {
        "updated": "Local status page settings updated",
        "updated_no_remote": "Updated after disabling remote status page",
        "apply_failed": "Local status page update failed",
    }
    message = labels.get(outcome, "Local status page update failed")
    code = str(status_code).strip()
    if code:
        message += " (HTTP " + code + ")"
    detail = clean_detail(detail)
    if detail and outcome == "apply_failed":
        message += " — " + detail
    return message


results = parse_list(sys.argv[1] if len(sys.argv) > 1 else "[]")

network_id = (sys.argv[2] if len(sys.argv) > 2 else "").strip()
network_name = (sys.argv[3] if len(sys.argv) > 3 else "").strip()
status_code = (sys.argv[4] if len(sys.argv) > 4 else "").strip()
error_detail = sys.argv[5] if len(sys.argv) > 5 else ""
update_path = (sys.argv[6] if len(sys.argv) > 6 else "standard").strip().lower()

try:
    code = int(str(status_code).strip() or 0)
except (TypeError, ValueError):
    code = 0
if code in SUCCESS_CODES:
    outcome = "updated_no_remote" if update_path == "retry_no_remote" else "updated"
    success = True
else:
    outcome = "apply_failed"
    success = False

entry = {
    "networkId": network_id,
    "networkName": network_name,
    "outcome": outcome,
    "success": success,
    "message": build_message(outcome, status_code, error_detail),
}

if status_code:
    entry["httpStatus"] = code

if update_path == "retry_no_remote":
    entry["updatePath"] = "retry_no_remote"

results.append(entry)
updated_list = json.dumps(results, separators=(",", ":"))

