"""
Format LSP Report — final workflow outputs.

  argv[1]  Local - Processed Networks
  argv[2]  Organization Name or ID

Script queries:
  report, status_message, status_code, error_message, result_json
"""

import sys
import json

OK_OUTCOMES = frozenset({"updated", "updated_no_remote"})


def parse_list(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def item_success(item):
    if "success" in item:
        return bool(item.get("success"))
    return str(item.get("outcome", "")).lower() in OK_OUTCOMES


def item_message(item):
    return str(item.get("message") or "").strip()


def count_outcomes(networks):
    counts = {
        "updated": 0,
        "updated_no_remote": 0,
        "apply_failed": 0,
    }
    for item in networks:
        outcome = str(item.get("outcome", "apply_failed")).lower()
        if outcome in counts:
            counts[outcome] += 1
        else:
            counts["apply_failed"] += 1
    return counts


def overall_status(networks):
    if not networks:
        return "Failed"
    failed = sum(1 for network in networks if not item_success(network))
    if failed == 0:
        return "Success"
    if failed < len(networks):
        return "Partial"
    return "Failed"


def status_code_for(status):
    if status == "Success":
        return 200
    if status == "Partial":
        return 207
    return 500


def build_report(org, status, counts, networks):
    lines = [
        "Local Status Page Bulk Update Report",
        "Organization: " + org,
        "Status: " + status,
        "",
        "Updated:              " + str(counts["updated"]),
        "Updated (no remote):  " + str(counts["updated_no_remote"]),
        "Failed:               " + str(counts["apply_failed"]),
        "",
        "Details",
        "-" * 40,
    ]

    if not networks:
        lines.append("No networks were processed.")
    else:
        for item in sorted(
            networks,
            key=lambda x: str(x.get("networkName") or x.get("networkId", "")).lower(),
        ):
            name = item.get("networkName") or item.get("networkId") or "unknown"
            outcome = item.get("outcome", "apply_failed")
            message = item_message(item)
            line = str(name) + " — " + outcome
            if message:
                line += " — " + message
            lines.append(line)

    return "\n".join(lines)


report = "Error generating report."
status_message = "Failed"
status_code = 500
error_message = "Error generating report."
result_json = "{}"

try:
    networks = parse_list(sys.argv[1] if len(sys.argv) > 1 else "[]")
    org = (sys.argv[2] if len(sys.argv) > 2 else "").strip() or "unknown"

    counts = count_outcomes(networks)
    status_message = overall_status(networks)
    status_code = status_code_for(status_message)

    if status_message == "Success":
        error_message = ""
    elif not networks:
        error_message = "No networks were processed."
    elif status_message == "Partial":
        error_message = (
            str(counts["apply_failed"])
            + " of "
            + str(len(networks))
            + " network(s) failed to update. See Result for per-network details."
        )
    else:
        error_message = (
            str(counts["apply_failed"])
            + " network(s) failed to update. See Result for per-network details."
        )

    report = build_report(org, status_message, counts, networks)

    result_json = json.dumps(
        {
            "overallStatus": status_message,
            "organization": org,
            "total": len(networks),
            "counts": counts,
            "networks": sorted(
                networks,
                key=lambda x: str(x.get("networkName") or x.get("networkId", "")).lower(),
            ),
        },
        separators=(",", ":"),
    )

except Exception as exc:
    script_error = "Error generating report: " + str(exc)
    report = script_error
    status_message = "Failed"
    status_code = 500
    error_message = script_error
    result_json = json.dumps(
        {
            "overallStatus": "Failed",
            "organization": (sys.argv[2] if len(sys.argv) > 2 else "").strip(),
            "total": 0,
            "counts": {},
            "networks": [],
            "error": script_error,
        },
        separators=(",", ":"),
    )
